#include <bits/stdc++.h>
using namespace std;

unordered_set<string> visited;
array<char, 256> cardRank{}, cardSuit{};

bool solve(vector<unsigned char>& cards) {
    if (cards.size() == 1) return true;

    string state(reinterpret_cast<const char*>(cards.data()), cards.size());
    if (!visited.insert(state).second) return false;

    int cur = static_cast<int>(cards.size()) - 1;
    unsigned char current = cards.back();

    auto matches = [](unsigned char a, unsigned char b) {
        return cardRank[a] == cardRank[b] || cardSuit[a] == cardSuit[b];
    };

    if (matches(cards[cur - 1], current)) {
        unsigned char old = cards[cur - 1];
        cards.pop_back();
        cards[cur - 1] = current;

        if (solve(cards)) return true;

        cards[cur - 1] = old;
        cards.push_back(current);
    }

    if (cur >= 3 && matches(cards[cur - 3], current)) {
        unsigned char old = cards[cur - 3];
        cards.pop_back();
        cards[cur - 3] = current;

        if (solve(cards)) return true;

        cards[cur - 3] = old;
        cards.push_back(current);
    }

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<unsigned char> cards;
    cards.reserve(n);

    map<pair<char, char>, unsigned char> id;
    unsigned int nextId = 0;

    for (int i = 0; i < n; ++i) {
        string card;
        cin >> card;

        pair<char, char> key = {card[0], card[1]};
        auto it = id.find(key);

        if (it == id.end()) {
            unsigned char value = static_cast<unsigned char>(nextId++);
            id[key] = value;
            cardRank[value] = card[0];
            cardSuit[value] = card[1];
            cards.push_back(value);
        } else {
            cards.push_back(it->second);
        }
    }

    cout << (solve(cards) ? "YES\n" : "NO\n");
    return 0;
}

