#include <bits/stdc++.h>
using namespace std;

unordered_set<string> visited;

string encode(const vector<string>& cards) {
    string key;
    key.reserve(cards.size() * 2);
    for (const string& card : cards) {
        key.push_back(card[0]);
        key.push_back(card[1]);
    }
    return key;
}

bool solve(const vector<string>& cards) {
    if (cards.size() == 1)
        return true;

    string state = encode(cards);
    if (!visited.insert(state).second)
        return false;

    int cur = static_cast<int>(cards.size()) - 1;

    if (cur > 0 &&
        (cards[cur - 1][0] == cards[cur][0] ||
         cards[cur - 1][1] == cards[cur][1])) {
        vector<string> next = cards;
        next[cur - 1] = next[cur];
        next.pop_back();
        if (solve(next))
            return true;
    }

    if (cur > 2 &&
        (cards[cur - 3][0] == cards[cur][0] ||
         cards[cur - 3][1] == cards[cur][1])) {
        vector<string> next = cards;
        next[cur - 3] = next[cur];
        next.pop_back();
        if (solve(next))
            return true;
    }

    return false;
}

