#include <bits/stdc++.h>
using namespace std;

unordered_set<string> visited;

bool solve(const string& state) {
    if (state.size() == 2) return true;
    if (!visited.insert(state).second) return false;

    const int piles = static_cast<int>(state.size() / 2);
    const int last = 2 * (piles - 1);

    auto matches = [&](int pos) {
        return state[pos] == state[last] ||
               state[pos + 1] == state[last + 1];
    };

    if (piles > 1) {
        int target = 2 * (piles - 2);
        if (matches(target)) {
            string next = state;
            next[target] = state[last];
            next[target + 1] = state[last + 1];
            next.resize(state.size() - 2);
            if (solve(next)) return true;
        }
    }

    if (piles > 3) {
        int target = 2 * (piles - 4);
        if (matches(target)) {
            string next = state;
            next[target] = state[last];
            next[target + 1] = state[last + 1];
            next.resize(state.size() - 2);
            if (solve(next)) return true;
        }
    }

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    string state;
    state.reserve(2 * n);

    for (int i = 0; i < n; ++i) {
        string card;
        cin >> card;
        state.push_back(card[0]);
        state.push_back(card[1]);
    }

    cout << (solve(state) ? "YES\n" : "NO\n");
    return 0;
}

